local autoToggle=addToggle(section,"Auto Get Tools",autoGetTools,function(state)
    local wasEnabled=autoGetTools
    autoGetTools=state
    toyOrderDirty=true
    SetCfg("autoGetTools",state)
    if state then
        if not wasEnabled then cancelToyRequests() end
